<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Utilisateurs · SAGASTOCK</title><style>:root{--orange:#f47a20;--dark:#382319;--soft:#fff7f0}*{box-sizing:border-box}body{margin:0;font-family:system-ui;background:var(--soft);color:var(--dark)}header{background:var(--orange);color:#fff;padding:18px 5%;display:flex;justify-content:space-between;align-items:center}main{padding:28px 5%;max-width:1300px;margin:auto}.card{background:#fff;padding:22px;border-radius:16px;box-shadow:0 10px 30px #7a350015;margin-bottom:22px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}input,select{width:100%;padding:11px;border:1px solid #dbcabd;border-radius:9px}.button,button{background:var(--orange);color:#fff;border:0;padding:11px 15px;border-radius:9px;font-weight:700;cursor:pointer}.secondary{background:#fff0e5;color:#9a4300}.success{background:#eaf8ef;color:#176b3a;padding:13px;border-radius:9px}.secret{background:#2f241e;color:#fff;padding:14px;border-radius:9px;font-family:monospace}.user{border-top:1px solid #f1e1d5;padding:18px 0}.user:first-child{border:0}.user-head{display:flex;justify-content:space-between;gap:12px}.roles{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.inline{display:inline}.muted{color:#78665a;font-size:14px}@media(max-width:800px){.grid{grid-template-columns:1fr}.user-head{display:block}}</style></head><body><header><strong>SAGASTOCK · Administration</strong><a style="color:white;margin-left:auto;margin-right:16px" href="{{ route('security.index') }}">Sécurité</a><a style="color:white;margin-right:16px" href="{{ route('profile.show') }}">Mon profil</a><form method="post" action="{{ route('logout') }}">@csrf<button class="secondary">Déconnexion</button></form></header><main><h1>Gestion des utilisateurs</h1>@if(session('success'))<p class="success">{{ session('success') }}</p>@endif @if(session('temporary_password'))<p class="secret">Mot de passe tempor